const projects={
  secondbrain:{title:'Second Brain',image:'second-brain-demo.png',alt:'Demonstração do Second Brain com dados fictícios',description:'Um workspace de organização pessoal para reunir tarefas, projetos, hábitos e notas. A prévia do portfólio usa uma demonstração independente com dados de exemplo.',points:['Visão geral de tarefas e hábitos em uma interface de produtividade.','Demonstração navegável: marque tarefas, registre hábitos e crie uma tarefa de exemplo.','Produto com versões web e desktop; o código-fonte de produção permanece privado.'],tech:['Next.js','TypeScript','NestJS','Prisma','PostgreSQL','Electron'],note:'Esta prévia é uma demonstração independente com dados fictícios. Não acessa contas ou dados do aplicativo de produção; as alterações ficam apenas nesta página.',live:'second-brain-demo.html',code:'https://github.com/natatgh/brain-control-desktop-releases/releases',codeLabel:'Versões desktop',liveLabel:'Abrir demonstração'},
  lumen:{title:'Lumen',image:'lumen.png',alt:'Captura real do site Lumen',description:'Uma aplicação para compartilhar tela em salas temporárias. Os participantes podem transmitir e assistir pelo navegador ou pelo cliente Windows.',points:['Mídia WebRTC entre participantes e sinalização com Supabase Realtime.','Controles de qualidade e diagnóstico de conexão.','Interface compartilhada entre a web e o cliente desktop.'],tech:['Next.js','TypeScript','WebRTC','Supabase'],note:'MVP para grupos pequenos e pessoas de confiança. A conectividade depende da rede e da configuração de STUN/TURN. O link abre a página inicial e não inicia captura de tela.',live:'https://screen-share-p2p.vercel.app/',code:'https://github.com/natatgh/screen-share-p2p'},
  finder:{title:'GitHub Profile Finder',image:'github-finder.png',alt:'Captura real de uma consulta ao perfil público Octocat no GitHub Profile Finder',description:'Uma interface para consultar perfis públicos do GitHub pelo nome de usuário, consumindo a API REST do GitHub.',points:['Informações do perfil, repositórios, seguidores e links.','Tratamento para usuário não encontrado, limite da API e falhas de rede.','JavaScript sem framework, com manipulação de DOM e fetch.'],tech:['JavaScript','GitHub REST API','HTML','CSS'],note:'Projeto de estudo do checkpoint de JavaScript do roadmap.sh. A imagem mostra uma consulta ao perfil público Octocat; os números podem mudar.',live:'https://git-community.vercel.app/',code:'https://github.com/natatgh/git-community'},
  spider:{title:'Spider-Man Multiverse',image:'spiderman.png',alt:'Captura real do Spider-Man Multiverse',description:'Um site temático sobre os filmes do Homem-Aranha, com navegação visual entre atores, trailers e sinopses.',points:['Navegação entre as diferentes versões do personagem.','Composição de páginas e interações em HTML, CSS e JavaScript.','Exploração de profundidade e movimento na apresentação dos filmes.'],tech:['JavaScript','HTML5','CSS3'],note:'Projeto de frontend sobre uma obra de terceiros. Personagens, imagens e filmes pertencem aos seus respectivos titulares.',live:'https://webpage-spider-man.vercel.app/',code:'https://github.com/natatgh/webpage-spider-man'},
  writings:{title:'Writings.dev',image:'writings.png',alt:'Captura real da página Writings.dev',description:'Prática de implementação de uma página editorial a partir de uma referência de design, seguindo o percurso de estudos do roadmap.sh.',points:['HTML semântico para estruturar a página e os artigos.','CSS Grid para a organização dos cards.','Adaptação de espaçamento e composição para diferentes telas.'],tech:['HTML','CSS','CSS Grid'],note:'Projeto educacional. O conteúdo dos artigos é demonstrativo e o design segue uma referência; não é apresentado como uma publicação editorial própria.',live:'https://writings-devs.vercel.app/',code:'https://github.com/natatgh/writings-devs'}
};
const dialog=document.querySelector('#project-dialog');
let opener;
function openProject(id){const p=projects[id];if(!p)return;opener=document.activeElement;document.querySelector('#dialog-content').innerHTML=`<img class="dialog-image" src="assets/${p.image}" alt="${p.alt}"><div class="dialog-copy"><h2 id="dialog-title">${p.title}</h2><p>${p.description}</p><ul>${p.points.map(s=>`<li>${s}</li>`).join('')}</ul><div class="tech-list">${p.tech.map(t=>`<span>${t}</span>`).join('')}</div><div class="project-actions"><a class="button dark" href="${p.live}" target="_blank" rel="noopener noreferrer">${p.liveLabel||'Abrir projeto'} ↗</a><a class="code-link" href="${p.code}" target="_blank" rel="noopener noreferrer">${p.codeLabel||'Ver código no GitHub'} ↗</a></div><p class="dialog-note">${p.note}</p></div>`;dialog.showModal();document.body.classList.add('modal-open');dialog.scrollTop=0;}
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>openProject(button.dataset.project)));
document.querySelector('#dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');if(opener?.isConnected)opener.focus();});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
const media=matchMedia('(prefers-reduced-motion: reduce)');let reduced=media.matches;
const motionButton=document.querySelector('#motion-toggle');
function setMotion(value){reduced=value;document.documentElement.classList.toggle('no-motion',reduced);motionButton.setAttribute('aria-pressed',String(reduced));motionButton.textContent=reduced?'Ativar movimento':'Reduzir movimento';window.dispatchEvent(new CustomEvent('portfolio-motion',{detail:{reduced}}));if(reduced)document.querySelectorAll('.tilt').forEach(el=>{el.style.removeProperty('--rx');el.style.removeProperty('--ry');});}
setMotion(reduced);media.addEventListener('change',e=>setMotion(e.matches));motionButton.addEventListener('click',()=>setMotion(!reduced));
document.querySelectorAll('.tilt').forEach(el=>{el.addEventListener('pointermove',e=>{if(reduced||e.pointerType!=='mouse')return;const r=el.getBoundingClientRect();const x=(e.clientX-r.left)/r.width-.5;const y=(e.clientY-r.top)/r.height-.5;el.style.setProperty('--rx',`${-y*3}deg`);el.style.setProperty('--ry',`${x*3}deg`);});el.addEventListener('pointerleave',()=>{el.style.removeProperty('--rx');el.style.removeProperty('--ry');});});
let notebookApi;let currentScreen='lumen';
function chooseScreen(id){const project=projects[id];if(!project)return;currentScreen=id;document.querySelectorAll('[data-screen]').forEach(b=>{const selected=b.dataset.screen===id;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});const link=document.querySelector('#showcase-link');link.innerHTML=`${project.title} <span>↗</span>`;link.href=project.live;const fallback=document.querySelector('.device-fallback');fallback.src='assets/'+project.image;fallback.alt=project.alt;if(notebookApi)notebookApi.setScreen(id);}
document.querySelectorAll('[data-screen]').forEach(button=>button.addEventListener('click',()=>chooseScreen(button.dataset.screen)));
const screenOrder=[...document.querySelectorAll('[data-screen]')].map(b=>b.dataset.screen);
document.querySelector('#screen-prev').addEventListener('click',()=>chooseScreen(screenOrder[(screenOrder.indexOf(currentScreen)+screenOrder.length-1)%screenOrder.length]));
document.querySelector('#screen-next').addEventListener('click',()=>chooseScreen(screenOrder[(screenOrder.indexOf(currentScreen)+1)%screenOrder.length]));
import('./notebook.js').then(({initNotebook})=>{notebookApi=initNotebook({reduced,initialScreen:currentScreen});}).catch(()=>{document.querySelector('#device-hint').textContent='Prévia do projeto';});
if(!reduced&&'IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('in-view');observer.unobserve(entry.target);}},{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>{el.classList.add('will-reveal');observer.observe(el);});}

